{
  "description": "The creature is a large quadrupedal mammal shown in side profile facing right against a plain light background. Its entire body except for the dorsal surface is covered in dense, long, shaggy brown fur that is darker on the legs and lighter on the muzzle and sides. The head is bear-like with a long snout. A single large glossy dark reddish-brown curved horn projects from the forehead. The back and shoulders are covered by a large, highly glossy, dark brown beetle-like exoskeleton consisting of a ridged oval shell over the mid and hind back and a spiky shield over the shoulders, with a row of small circular openings visible along the lower edge where the shell meets the fur.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with an elongated snout, black nose, small dark brown eyes, light tan muzzle, and dense brown fur",
      "where": "at the front end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark reddish-brown to black horn curving upward and backward with a smaller forward-pointing tine on its front edge and a shiny base on the forehead",
      "where": "arising from the center of the forehead between the eyes and ears, extending up and forward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry brown ears with dense fur",
      "where": "on top of the head behind the horn, one more visible than the other"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy columnar legs covered in long shaggy dark brown fur",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with blunt light brown claws visible at the toes and fur covering the tops",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small short stubby furry brown tail",
      "where": "at the extreme rear of the body, partially obscured behind the shell and hind leg fur"
    },
    {
      "part": "shell",
      "looks_like": "large oval highly glossy dark brown beetle elytra with fine longitudinal ridges and horizontal striations, with a thin dark rim and a row of seven small circular spiracle-like openings along its lower edge where it meets the fur",
      "where": "covering the dorsal surface from behind the shoulders to the rump, over the mid and hind back"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark reddish-brown pronotal shield with pointed lateral spikes and a smooth reflective surface, separate from but abutting the main shell",
      "where": "covering the shoulder and neck area directly in front of the main shell and behind the head"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
